"use client";
import { useEffect, useState } from "react";
import Link from "next/link";
import { ArrowLeft, Calendar, MapPin, TriangleAlert } from "lucide-react";
import Button from "@/components/Button";
type Data = { stallName?: string; status: string; event: { title: string; description: string; startDate: string; endDate: string; venue: string; category: string; status: string; isOnline?: boolean; organizer?: { name?: string }; images?: string[] } };
export default function VendorEventDetails({ params }: { params: Promise<{ id: string }> }) { const [data, setData] = useState<Data | null>(null); const [error, setError] = useState(""); useEffect(() => { params.then(({ id }) => fetch(`/api/vendors/events/${id}`, { cache: "no-store" }).then(async (r) => { const j = await r.json(); if (!r.ok || !j.success) throw new Error(j.error?.message || "Unable to load assigned event."); setData(j.data); }).catch((e) => setError(e instanceof Error ? e.message : "Unable to load assigned event."))); }, [params]); return <section className="my-4 mx-2 px-4 font-cause text-text-dark md:mx-3 lg:mx-4 xl:mx-6"><Link href="/vendor/events"><Button text="Back to My Events" variant="secondary" size="sm" iconLeft={<ArrowLeft size={16}/>}/></Link>{error && <p className="mt-6 rounded-xl border border-red-300 bg-red-50 p-4 text-red-700"><TriangleAlert className="mr-2 inline" size={18}/>{error}</p>}{!data && !error && <p className="mt-6">Loading assigned event...</p>}{data && <article className="mt-6 overflow-hidden rounded-xl border border-brown-normal"><div className="h-64 bg-brown-light">{data.event.images?.[0] && <img src={data.event.images[0]} alt="" className="h-full w-full object-cover"/>}</div><div className="p-5 md:p-8"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-sm capitalize text-text-light">{data.event.category}</p><h1 className="font-dynapuff text-2xl font-bold md:text-3xl">{data.event.title}</h1></div><span className="rounded-full bg-brown-light px-3 py-1 text-sm capitalize">{data.status} stall</span></div><div className="mt-6 grid gap-4 rounded-xl bg-brown-light p-4 md:grid-cols-2"><p><Calendar className="mr-2 inline" size={18}/><b>Starts:</b> {new Date(data.event.startDate).toLocaleString()}</p><p><Calendar className="mr-2 inline" size={18}/><b>Ends:</b> {new Date(data.event.endDate).toLocaleString()}</p><p><MapPin className="mr-2 inline" size={18}/><b>Location:</b> {data.event.isOnline ? "Online event" : data.event.venue}</p><p><b>Organizer:</b> {data.event.organizer?.name ?? "Event organizer"}</p>{data.stallName && <p><b>Your stall:</b> {data.stallName}</p>}<p><b>Event status:</b> <span className="capitalize">{data.event.status}</span></p></div><div className="mt-6"><h2 className="font-dynapuff text-xl">Event Description</h2><p className="mt-2 whitespace-pre-wrap leading-relaxed text-text-light">{data.event.description}</p></div></div></article>}</section>; }
